// Interactive "All campaigns" index on the Science Campaigns overview page.
// Data: docs/campaigns/campaigns.json, generated by scripts/build_campaign_index.py.
(function () {
  "use strict";
  // Resolve campaigns.json relative to THIS script's URL so it works under the
  // GitHub-Pages project subpath, mirroring software-dashboard.js.
  var SCRIPT_SRC = (document.currentScript && document.currentScript.src) || "";
  var DATA_URL = SCRIPT_SRC ? new URL("../campaigns/campaigns.json", SCRIPT_SRC).href : "campaigns.json";

  var CACHE = null;

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }
  function el(id) { return document.getElementById(id); }

  function filters() {
    return {
      q: (el("ci-search").value || "").trim().toLowerCase(),
      category: el("ci-category").value || "",
      system: el("ci-system").value || "",
    };
  }

  function matches(c, f) {
    if (f.category && c.category !== f.category) return false;
    if (f.system && c.systems.indexOf(f.system) === -1) return false;
    if (f.q) {
      var hay = (c.title + " " + c.kind + " " + c.systemsRaw + " " + c.outcome).toLowerCase();
      if (hay.indexOf(f.q) === -1) return false;
    }
    return true;
  }

  function draw() {
    if (!CACHE) return;
    var f = filters();
    var rows = CACHE.campaigns.filter(function (c) { return matches(c, f); });
    var h = ['<p class="sw-count">' + rows.length + " of " + CACHE.campaigns.length + " campaigns</p>"];
    h.push('<table class="sw-table"><thead><tr><th>Campaign</th><th>Category</th>' +
      "<th>System(s)</th><th>Outcome</th></tr></thead><tbody>");
    rows.forEach(function (c) {
      h.push('<tr><td><a href="' + esc(c.path) + '">' + esc(c.title) + "</a>" +
        (c.kind ? '<span class="sw-app-cat">' + esc(c.kind) + "</span>" : "") +
        "</td><td>" + esc(c.categoryLabel) +
        "</td><td>" + esc(c.systems.length ? c.systems.join(", ") : c.systemsRaw) +
        '</td><td><span class="sw-tag sw-' + esc(c.outcomeClass) + '">' + esc(c.outcome) +
        "</span></td></tr>");
    });
    h.push("</tbody></table>");
    el("ci-table").innerHTML = rows.length ? h.join("") : "";
    el("ci-empty").hidden = !!rows.length;
  }

  function populate(data) {
    var catSel = el("ci-category"), sysSel = el("ci-system");
    if (catSel.options.length <= 1) {
      var seen = {};
      data.campaigns.forEach(function (c) {
        if (seen[c.category]) return;
        seen[c.category] = 1;
        var o = document.createElement("option");
        o.value = c.category; o.textContent = c.categoryLabel; catSel.appendChild(o);
      });
    }
    if (sysSel.options.length <= 1) {
      var systems = {};
      data.campaigns.forEach(function (c) {
        c.systems.forEach(function (s) { systems[s] = 1; });
      });
      Object.keys(systems).sort().forEach(function (s) {
        var o = document.createElement("option");
        o.value = s; o.textContent = s; sysSel.appendChild(o);
      });
    }
  }

  function init() {
    var host = el("ci-index");
    if (!host) return;  // not on the campaigns overview page
    ["ci-search", "ci-category", "ci-system"].forEach(function (id) {
      var node = el(id);
      if (node && !node._wired) {
        node._wired = true;
        node.addEventListener("input", draw);
        node.addEventListener("change", draw);
      }
    });
    if (CACHE) { populate(CACHE); draw(); return; }
    fetch(DATA_URL).then(function (r) { return r.json(); }).then(function (data) {
      CACHE = data;
      populate(data);
      draw();
    }).catch(function (e) {
      host.innerHTML = '<p class="sw-empty">Could not load campaigns.json: ' + esc(e) + "</p>";
    });
  }

  // document$ fires on initial load AND after every instant-navigation.
  if (window.document$ && typeof window.document$.subscribe === "function") {
    window.document$.subscribe(init);
  } else if (document.readyState !== "loading") {
    init();
  } else {
    document.addEventListener("DOMContentLoaded", init);
  }
})();
